		if err != nil {
			continue
		}
		var record RunRecord
		if json.Unmarshal(data, &record) == nil && record.ID != "" {
			records = append(records, record)
		}
	}
	sort.Slice(records, func(i, j int) bool { return records[i].ID < records[j].ID })

	encoded, err := json.MarshalIndent(records, "", "  ")
	if err != nil {
